{
    rSidebarWin.SetAccessibleRole(css::accessibility::AccessibleRole::COMMENT);
}
SidebarWinAccessible::~SidebarWinAccessible() {}
void SidebarWinAccessible::ChangeSidebarItem(const SwAnnotationItem& rSidebarItem)
{
